<script module lang="ts">
/**
 * A read-only picture (`design/components/image.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/image.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, devWarning, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/image.module.css'

export interface ImageProps {
  /**
   * The accessible name. An empty string declares the picture decorative and hides it from
   * assistive technology. Required, because only the caller knows which of the two a picture is.
   */
  alt: string
  /**
   * Width over height of a frame the picture sits in, for a source whose size is unknown or is
   * not the shape wanted. Alone, the frame is as wide as its container. With `width` and
   * `height`, it replaces their ratio.
   */
  aspectRatio?: number
  /**
   * The element's CORS mode. Absent, the request is made without CORS.
   */
  crossOrigin?: 'anonymous' | 'use-credentials'
  /**
   * How the browser ranks this fetch among the page's others. `high` is for the one picture that
   * is the first view's largest content, with `loading="eager"`. Absent, the browser decides.
   */
  fetchPriority?: 'auto' | 'high' | 'low'
  /**
   * How the picture sits in a frame whose ratio is not its own: `contain` shows all of it,
   * `cover` fills the frame and crops. Defaults to `contain`, because cropping removes content.
   */
  fit?: 'contain' | 'cover'
  /**
   * The picture's height in CSS pixels, given together with `width`.
   */
  height?: number
  /**
   * When the browser fetches the picture: `lazy` as the reader nears it, `eager` at once.
   * Defaults to `lazy`.
   */
  loading?: 'lazy' | 'eager'
  /**
   * The element's referrer policy. Absent, the page's own policy applies.
   */
  referrerPolicy?:
    | 'no-referrer'
    | 'no-referrer-when-downgrade'
    | 'origin'
    | 'origin-when-cross-origin'
    | 'same-origin'
    | 'strict-origin'
    | 'strict-origin-when-cross-origin'
    | 'unsafe-url'
  /**
   * The picture's URL. An empty string is the failed state: there is nothing to request.
   */
  src: string
  /**
   * Other files of the same picture, in the element's `srcset` form: each a URL with a width
   * (`640w`) or a density (`2x`). The browser picks one for the screen, and one that does not
   * read the set requests `src`. For a set that gives widths the member writes the element's
   * `sizes` from the frame's box, so no caller writes a length, and the frame needs a box:
   * without one the set is ignored.
   */
  srcSet?: string
  /**
   * The picture's width in CSS pixels, given together with `height`. The two reserve the box
   * before the picture loads and are its natural size; the frame is never wider than its
   * container.
   */
  width?: number
}
</script>

<script lang="ts">
let {
  alt,
  aspectRatio,
  crossOrigin,
  fetchPriority,
  fit = 'contain',
  height,
  loading = 'lazy',
  referrerPolicy,
  src,
  srcSet,
  width,
}: ImageProps = $props()
const joined = joinSlot(undefined, () => ({}))
let loaded = $state('')
let failed = $state('')
let image = $state<HTMLElement | null>(null)
const ratio = $derived(
  aspectRatio !== undefined && aspectRatio > 0 && Number.isFinite(aspectRatio)
    ? aspectRatio
    : width !== undefined && height !== undefined && width > 0 && height > 0
      ? width / height
      : undefined,
)
const sized = $derived(ratio !== undefined)
const widths = $derived(srcSet !== undefined && /\d+w\s*(?:,|$)/.test(srcSet))
const candidates = $derived(widths && !sized ? undefined : srcSet)
const request = $derived(candidates === undefined ? src : src + ' ' + candidates)
const status = $derived(
  src === '' || failed === request ? 'failed' : loaded === request ? 'loaded' : 'loading',
)
const spread = $derived(
  width !== undefined &&
    height !== undefined &&
    width > 0 &&
    height > 0 &&
    ratio !== undefined &&
    fit === 'cover'
    ? Math.max(1, Math.round((width / height / ratio) * 100) / 100)
    : 1,
)
const sizes = $derived(
  !widths || !sized
    ? undefined
    : width !== undefined && height !== undefined && width > 0 && height > 0
      ? (loading === 'lazy' && spread === 1 ? 'auto, ' : '') +
        '(max-width: ' +
        width +
        'px) ' +
        Math.round(100 * spread) +
        'vw, ' +
        Math.round(width * spread) +
        'px'
      : loading === 'lazy' && fit !== 'cover'
        ? 'auto, 100vw'
        : undefined,
)
const decorative = $derived(alt === '')
const settle = $derived(() => {
  if (failed !== request) failed = ''
  const element = image as HTMLImageElement | null | undefined
  if (element == null || !element.complete) return
  if (element.naturalWidth > 0) loaded = request
  else element.src = src
})
const effect1 = () => {
  settle()
}
watchEffect(effect1, { watch: () => request })
const effect2 = () => {
  devWarning(
    (width === undefined) !== (height === undefined),
    'Image: `width` and `height` are given together. One alone gives no ratio and is ignored.',
  )
}
watchEffect(effect2, { watch: () => (width === undefined) !== (height === undefined) })
const effect3 = () => {
  devWarning(
    widths && !sized,
    'Image: a `srcSet` that gives widths needs a box, from `width` and `height` or from `aspectRatio`. Without one the set is ignored.',
  )
}
watchEffect(effect3, { watch: () => widths && !sized })
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span
    class={styles.frame}
    style:aspect-ratio={ratio}
    style:inline-size={width !== undefined && height !== undefined && width > 0 && height > 0 ? `${width}px` : undefined}
    data-state={status === 'loaded' ? undefined : status}
    data-fit={fit}
    data-sized={(sized) ? '' : undefined}
    data-member="image"
    >{#if status === 'loading'}<span class={styles.placeholder} aria-hidden="true"></span>{/if
    }{#if status === 'failed'
      }<span
        class={styles.fallback}
        data-image-part="fallback"
        role={(!decorative) ? 'img' : undefined}
        aria-label={(!decorative) ? alt : undefined}
        aria-hidden={(decorative) ? true : undefined}
        ><Icon name="error"
      /></span
    >{:else
      }<img
        bind:this={image}
        class={styles.image}
        {loading}
        fetchpriority={fetchPriority}
        crossorigin={crossOrigin}
        referrerpolicy={referrerPolicy}
        {sizes}
        srcset={candidates}
        {src}
        {alt}
        onload={() => { loaded = request }}
        onerror={() => { failed = request }}
    />{/if
  }</span
>{/if
}{@render joined.end?.()}
